param([string]$DatabaseUrl=$env:OPPORTUNITY_TEST_DATABASE_URL)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($DatabaseUrl)){throw 'Explicit disposable loopback database URL required'};$uri=[Uri]$DatabaseUrl;if($uri.Host-notin@('127.0.0.1','localhost','::1')-or$DatabaseUrl-match'(?i)supabase'){throw 'Refusing unsafe database'}
$psql='C:\Program Files\PostgreSQL\15\bin\psql.exe';if(-not(Test-Path $psql)){$psql=(Get-Command psql).Source}
function StartSql([string]$sql){$i=[Diagnostics.ProcessStartInfo]::new($psql);$i.UseShellExecute=$false;$i.CreateNoWindow=$true;$i.RedirectStandardError=$true;$i.RedirectStandardOutput=$true;$i.Arguments="-X -v ON_ERROR_STOP=1 -d `"$DatabaseUrl`" -c `"$sql`"";[Diagnostics.Process]::Start($i)}
&$psql -X -v ON_ERROR_STOP=1 -q -d $DatabaseUrl -c "insert into public.acquisition_opportunities(id,name,created_by_email,updated_by_email)values('74000000-0000-4000-8000-000000000001','Race Opportunity','fixture@upperlineco.com','fixture@upperlineco.com'),('74000000-0000-4000-8000-000000000002','Replay Opportunity','fixture@upperlineco.com','fixture@upperlineco.com'),('74000000-0000-4000-8000-000000000003','Release Opportunity','fixture@upperlineco.com','fixture@upperlineco.com');insert into public.intelligence_entities(id,entity_type,display_name,created_by_email)values('74000000-0000-4000-8000-000000000099','organization','Not Property','fixture@upperlineco.com');"
if($LASTEXITCODE-ne 0){throw 'concurrency fixture failed'}
$a=StartSql "set role service_role;select * from public.resolve_intelligence_opportunity_primary_target_v1('75000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001','confirm','new_property',null,'Race A','[]',null,'one@upperlineco.com');";$b=StartSql "set role service_role;select * from public.resolve_intelligence_opportunity_primary_target_v1('75000000-0000-4000-8000-000000000002','74000000-0000-4000-8000-000000000001','confirm','new_property',null,'Race B','[]',null,'two@upperlineco.com');";$a.WaitForExit();$b.WaitForExit();if((@($a.ExitCode,$b.ExitCode)|Where-Object{$_-eq 0}).Count-ne 1){throw "conflicting confirmation race expected one winner: $($a.ExitCode),$($b.ExitCode)"};Write-Host 'RACE 1 conflicting confirmations PASS'
$sql="set role service_role;select * from public.resolve_intelligence_opportunity_primary_target_v1('75000000-0000-4000-8000-000000000003','74000000-0000-4000-8000-000000000002','confirm','new_property',null,'Replay Property','[]',null,'one@upperlineco.com');";$a=StartSql $sql;$b=StartSql $sql;$a.WaitForExit();$b.WaitForExit();if($a.ExitCode-ne 0-or$b.ExitCode-ne 0){throw 'identical replay race failed'};$count=(&$psql -X -At -d $DatabaseUrl -c "select count(*) from public.intelligence_opportunity_subjects where opportunity_id='74000000-0000-4000-8000-000000000002'").Trim();if($count-ne'1'){throw "replay created $count subjects"};Write-Host 'RACE 2 identical replay PASS'
$failed=StartSql "set role service_role;select * from public.resolve_intelligence_opportunity_primary_target_v1('75000000-0000-4000-8000-000000000004','74000000-0000-4000-8000-000000000003','confirm','existing_property','74000000-0000-4000-8000-000000000099',null,'[]',null,'one@upperlineco.com');";$failed.WaitForExit();if($failed.ExitCode-eq 0){throw 'expected failed transaction'};$success=StartSql "set role service_role;select * from public.resolve_intelligence_opportunity_primary_target_v1('75000000-0000-4000-8000-000000000005','74000000-0000-4000-8000-000000000003','confirm','new_property',null,'After Failure','[]',null,'one@upperlineco.com');";$success.WaitForExit();if($success.ExitCode-ne 0){throw "failed transaction leaked lock: $($success.StandardError.ReadToEnd())"};$locks=(&$psql -X -At -d $DatabaseUrl -c "select count(*) from pg_locks where locktype='advisory' and pid<>pg_backend_pid()").Trim();if($locks-ne'0'){throw "leaked $locks advisory locks"};Write-Host 'RACE 3 failed transaction lock release PASS'
